/* ── js/registry.js ── */








const SURFACES = {
  [mobileSurface.id]: mobileSurface,
  [websiteSurface.id]: websiteSurface,
};

const EPICS = {
  mobile: mobileEpics,
  website: websiteEpics,
};

const EPIC_SCREENS = {
  mobile: {
    signup: signupScreens,
    "signup-current": signupCurrentScreens,
  },
  website: {
    "dashboard-setup": dashboardSetupScreens,
  },
};

function epicsFor(surfaceId) {
  return EPICS[surfaceId] || {};
}

function firstEpicId(surfaceId) {
  return Object.keys(epicsFor(surfaceId))[0] || "";
}

function screensFor(surfaceId, epicId) {
  return EPIC_SCREENS[surfaceId]?.[epicId] || [];
}


/* ── js/nav.js ── */



function isWebsite() {
  return state.surface === "website";
}

function activeEpic() {
  return epicsFor(state.surface)[state.epic] || null;
}

function activeFlow() {
  return screensFor(state.surface, state.epic);
}

function compareFlowId() {
  return isWebsite() ? "" : activeEpic()?.compareFlow || "";
}

function oldFlow() {
  const id = compareFlowId();
  return id ? screensFor("mobile", id) : [];
}

function isDualJourney() {
  return Boolean(compareFlowId());
}

function isComparing() {
  return isDualJourney() && !state.journeySolo;
}

function isSoloOld() {
  return isDualJourney() && state.journeySolo === "old";
}

function previewRoot() {
  return isWebsite() ? els.webScreen : els.phoneScreen;
}

function currentScreenId() {
  return activeFlow()[state.current]?.id || "";
}

function routeHash(surface, epic, screen) {
  const parts = [surface, epic];
  if (screen) parts.push(screen);
  return `#/${parts.join("/")}`;
}

function parseRoute() {
  const raw = (window.location.hash || "").replace(/^#\/?/, "").trim();
  const parts = raw.split("/").filter(Boolean);
  let surface = parts[0];
  let epic = parts[1];
  const screen = parts[2] || "";
  if (!SURFACES[surface]) surface = "mobile";
  if (!epicsFor(surface)[epic]) epic = firstEpicId(surface) || "";
  const flow = screensFor(surface, epic);
  let index = screen ? flow.findIndex((step) => step.id === screen) : 0;
  if (index < 0) index = 0;
  return { surface, epic, index };
}

function writeRoute(mode = "replace") {
  const hash = routeHash(state.surface, state.epic, currentScreenId());
  if (window.location.hash === hash) return;
  if (mode === "push") history.pushState(null, "", hash);
  else history.replaceState(null, "", hash);
}

function routeMatchesState(route) {
  return state.surface === route.surface
    && state.epic === route.epic
    && state.current === route.index;
}

function showFirstSteps(index, oldIndex) {
  goTo(index, { fromRoute: true, skipBind: isDualJourney() });
  if (isDualJourney()) goToOld(oldIndex, { fromRoute: true });
}

function applyRoute() {
  const route = parseRoute();
  const switched = state.surface !== route.surface || state.epic !== route.epic;
  state.surface = route.surface;
  state.epic = route.epic;
  if (switched) {
    pauseDemo();
    state.journeySolo = null;
    state.oldCurrent = 0;
  }
  hooks.applySurfaceClass();
  showFirstSteps(route.index, state.oldCurrent);
  writeRoute("replace");
  if (switched) hooks.fitPreview();
}

function onRouteChange() {
  if (routeMatchesState(parseRoute())) return;
  applyRoute();
}

function updatePlayState() {
  if (!els.btnPlay || !els.btnPause) return;
  els.btnPlay.classList.toggle("active", state.isPlaying);
  els.btnPlay.setAttribute("aria-pressed", String(state.isPlaying));
  els.btnPause.classList.toggle("active", !state.isPlaying);
  els.btnPause.setAttribute("aria-pressed", String(!state.isPlaying));
}

function playDemo() {
  state.isPlaying = true;
  setupAutoplay();
  updatePlayState();
}

function pauseDemo() {
  state.isPlaying = false;
  clearInterval(state.autoplayTimer);
  updatePlayState();
}

function nextIndex(index, length) {
  return index < length - 1 ? index + 1 : 0;
}

function setupAutoplay() {
  clearInterval(state.autoplayTimer);
  if (!state.isPlaying || !activeFlow().length) return;
  const seconds = Number(els.autoplaySpeed.value);
  state.autoplayTimer = setInterval(() => {
    if (isComparing()) {
      goTo(nextIndex(state.current, activeFlow().length), { skipBind: true, skipChrome: true });
      goToOld(nextIndex(state.oldCurrent, oldFlow().length));
      return;
    }
    if (isSoloOld()) {
      goToOld(nextIndex(state.oldCurrent, oldFlow().length));
      return;
    }
    goTo(nextIndex(state.current, activeFlow().length));
  }, seconds * 1000);
}

function showPhoneStep(host, flowId, stepId) {
  if (!host) return;
  host.querySelectorAll(".screen").forEach((el) => {
    el.classList.toggle("active", el.dataset.flow === flowId && el.dataset.screen === stepId);
  });
}

function isOldHost(host) {
  return Boolean(
    host && els.oldPhoneScreen && (host === els.oldPhoneScreen || els.oldPhoneScreen.contains(host))
  );
}

function setBar(label, fill, text, ratio) {
  if (label) label.textContent = text;
  if (fill) fill.style.width = `${ratio * 100}%`;
}

function updateProgress() {
  const flow = activeFlow();
  const old = oldFlow();
  const comparing = isComparing();
  const soloOld = isSoloOld();
  const showOldBar = comparing || soloOld;
  const showNewBar = !soloOld;

  if (els.oldFlowProgress) els.oldFlowProgress.hidden = !showOldBar;
  if (els.oldProgressTrack) els.oldProgressTrack.hidden = !showOldBar;
  if (els.flowProgress) els.flowProgress.hidden = !showNewBar;
  if (els.progressTrack) els.progressTrack.hidden = !showNewBar;

  const prefix = isDualJourney() ? "Idea " : "";
  setBar(
    els.flowProgress,
    els.progressFill,
    flow.length ? `${prefix}${state.current + 1} / ${flow.length}` : "0 / 0",
    flow.length ? (state.current + 1) / flow.length : 0
  );
  if (showOldBar && old.length) {
    setBar(
      els.oldFlowProgress,
      els.oldProgressFill,
      `Current ${state.oldCurrent + 1} / ${old.length}`,
      (state.oldCurrent + 1) / old.length
    );
  }

  const atStart = soloOld ? state.oldCurrent === 0 : state.current === 0;
  const atEnd = soloOld ? state.oldCurrent >= old.length - 1 : state.current >= flow.length - 1;
  if (els.prevBtn) els.prevBtn.disabled = comparing ? atStart && state.oldCurrent === 0 : atStart;
  if (els.nextBtn) {
    els.nextBtn.disabled = comparing ? atEnd && state.oldCurrent >= old.length - 1 : atEnd;
  }
  syncPhoneSteppers(old, flow);
}

function syncPhoneSteppers(old, flow) {
  document.querySelectorAll("[data-step-journey]").forEach((btn) => {
    const which = btn.dataset.stepJourney;
    const delta = Number(btn.dataset.stepDelta);
    const atStart = which === "old" ? state.oldCurrent === 0 : state.current === 0;
    const atEnd = which === "old"
      ? !old.length || state.oldCurrent >= old.length - 1
      : !flow.length || state.current >= flow.length - 1;
    btn.disabled = delta < 0 ? atStart : atEnd;
  });
}

function refreshAfterGo(opts = {}) {
  if (!opts.skipBind) {
    try {
      hooks.bindActiveScreen();
    } catch (err) {
      console.error("bindActiveScreen failed", err);
    }
  }
  if (!opts.fromRoute) writeRoute("replace");
  if (!opts.skipChrome) {
    updateProgress();
    hooks.updateChrome();
    requestAnimationFrame(() => hooks.fitPreview());
  }
}

function goTo(index, opts = {}) {
  const flow = activeFlow();
  if (!flow.length) {
    state.current = 0;
    updateProgress();
    hooks.updateChrome();
    if (!opts.fromRoute) writeRoute("replace");
    requestAnimationFrame(() => hooks.fitPreview());
    return;
  }

  state.current = Math.max(0, Math.min(flow.length - 1, index));
  const step = flow[state.current];
  showPhoneStep(previewRoot(), state.epic, step.id);
  if (els.webUrl && step.url) els.webUrl.textContent = step.url;
  refreshAfterGo(opts);
}

function goToOld(index, opts = {}) {
  const flow = oldFlow();
  if (!flow.length || !els.oldPhoneScreen) return;
  state.oldCurrent = Math.max(0, Math.min(flow.length - 1, index));
  showPhoneStep(els.oldPhoneScreen, compareFlowId(), flow[state.oldCurrent].id);
  refreshAfterGo({ ...opts, fromRoute: true });
}

function setJourneySolo(which) {
  if (!isDualJourney() && which) return;
  state.journeySolo = which || null;
  hooks.applySurfaceClass();
  updateProgress();
  hooks.updateChrome();
  requestAnimationFrame(() => hooks.fitPreview());
}

function stepJourney(which, delta) {
  if (which === "old") {
    goToOld(state.oldCurrent + delta);
    return;
  }
  goTo(state.current + delta);
}

function clampStep(index, length, delta) {
  return Math.max(0, Math.min(length - 1, index + delta));
}

function stepBoth(delta) {
  if (isSoloOld()) {
    goToOld(state.oldCurrent + delta);
    return;
  }
  if (!isComparing()) {
    goTo(state.current + delta);
    return;
  }
  goTo(clampStep(state.current, activeFlow().length, delta), { skipBind: true, skipChrome: true });
  goToOld(clampStep(state.oldCurrent, oldFlow().length, delta), { skipBind: true, skipChrome: true });
  refreshAfterGo();
}

function activateLooseScreen(host, id) {
  const el = host?.querySelector(`.screen[data-screen="${id}"]`);
  if (!el) return;
  el.parentElement?.querySelectorAll(".screen").forEach((screen) => screen.classList.remove("active"));
  el.classList.add("active");
}

function goToId(id, opts = {}) {
  const host = opts.host;
  if (isOldHost(host)) {
    const oldIndex = oldFlow().findIndex((step) => step.id === id);
    if (oldIndex >= 0) goToOld(oldIndex);
    else activateLooseScreen(els.oldPhoneScreen, id);
    return;
  }
  const index = activeFlow().findIndex((step) => step.id === id);
  if (index >= 0) {
    goTo(index);
    return;
  }
  activateLooseScreen(host || previewRoot(), id);
}


/* ── features/website/dashboard-setup/shared/studio-state.js ── */
const studioChoice = { template: "Shop sales" };

function setStudioTemplate(name) {
  studioChoice.template = name;
}

function studioTemplateName() {
  return studioChoice.template;
}


/* ── features/website/dashboard-setup/studio-template/studio-template.js ── */


function bindStudioTemplate() {
  const canvas = document.querySelector('[data-feature-canvas="studio-template"]');
  if (!canvas) return;
  const continueBtn = canvas.querySelector("#studioTemplateContinue");
  const cards = canvas.querySelectorAll("[data-template]");
  cards.forEach((card) => {
    card.onclick = () => {
      cards.forEach((other) => other.classList.toggle("is-selected", other === card));
      setStudioTemplate(card.dataset.template);
      if (continueBtn) continueBtn.disabled = false;
    };
  });
}


/* ── features/website/dashboard-setup/studio-dashboard/studio-dashboard.js ── */


function bindStudioDashboard() {
  const label = document.getElementById("studioDashboardTemplate");
  if (label) label.textContent = studioTemplateName();
}


/* ── features/website/dashboard-setup/index.js ── */




function bindDashboardSetup() {
  bindStudioTemplate();
  bindStudioDashboard();
}


/* ── js/bind.js ── */



function bindActiveScreen() {
  document.querySelectorAll("[data-goto]").forEach((el) => {
    el.onclick = (event) => {
      event.preventDefault();
      goToId(el.dataset.goto, { host: el.closest(".phone-screen") });
    };
  });
  bindDashboardSetup();
}


/* ── js/mount.js ── */




const EMPTY_HTML = `
  <div class="screen active" data-screen="empty">
    <div class="screen-code">
      <div class="phone-empty">
        <p class="phone-empty-label">Ready</p>
        <p class="phone-empty-hint">Add your first screen to start</p>
      </div>
    </div>
  </div>`;

const WEB_EMPTY_HTML = `
  <div class="web-empty">
    <p class="web-empty-label">Desktop</p>
    <p class="web-empty-hint">Add your first screen to start</p>
  </div>`;

function screenMarkup(id) {
  return `<div class="screen-code">${screenTemplates[id] || ""}</div>`;
}

function flowScreens(surfaceId, flowId) {
  return screensFor(surfaceId, flowId).map((screen) => ({ ...screen, flow: flowId }));
}

function mountFlow(host, screens, emptyHtml) {
  if (!host) return;
  if (!screens.length) {
    host.innerHTML = emptyHtml;
    return;
  }
  host.innerHTML = "";
  screens.forEach((screen, index) => {
    const el = document.createElement("div");
    el.className = "screen" + (index === 0 ? " active" : "");
    el.dataset.screen = screen.id;
    el.dataset.flow = screen.flow;
    el.innerHTML = screenMarkup(screen.id);
    host.appendChild(el);
  });
}

function mountMobileScreens() {
  const epics = Object.values(epicsFor("mobile"));
  const ideaScreens = epics.flatMap((epic) => flowScreens("mobile", epic.id));
  const currentScreens = epics
    .filter((epic) => epic.compareFlow)
    .flatMap((epic) => flowScreens("mobile", epic.compareFlow));
  mountFlow(els.phoneScreen, ideaScreens, EMPTY_HTML);
  mountFlow(els.oldPhoneScreen, currentScreens, EMPTY_HTML);
}

function mountWebsiteScreens() {
  const screens = Object.keys(epicsFor("website")).flatMap((epicId) => flowScreens("website", epicId));
  mountFlow(els.webScreen, screens, WEB_EMPTY_HTML);
}

function mountScreens() {
  mountMobileScreens();
  mountWebsiteScreens();
}


/* ── features/shell/shell.js ── */




const ELEMENT_IDS = [
  "epicChips",
  "sidebarEpicName",
  "sidebarEpicDesc",
  "scopeHint",
  "flowProgress",
  "progressFill",
  "progressTrack",
  "oldFlowProgress",
  "oldProgressFill",
  "oldProgressTrack",
  "phoneScreen",
  "oldPhoneScreen",
  "journeyRow",
  "soloOldBtn",
  "soloNewBtn",
  "undoSoloBtn",
  "phoneColumn",
  "webColumn",
  "webScreen",
  "webUrl",
  "surfaceSwitch",
  "scopeEmptyPhone",
  "demoBar",
  "btnPlay",
  "btnPause",
  "autoplayHint",
  "autoplaySpeed",
  "prevBtn",
  "nextBtn",
];

function cacheElements() {
  ELEMENT_IDS.forEach((id) => {
    els[id] = document.getElementById(id);
  });
}

function applySurfaceClass() {
  const root = document.documentElement.classList;
  root.toggle("surface-mobile", state.surface === "mobile");
  root.toggle("surface-website", state.surface === "website");
  root.toggle("journey-solo-old", state.journeySolo === "old");
  root.toggle("journey-solo-new", state.journeySolo === "new");
  root.toggle("journey-dual", isDualJourney());
}

function renderEpicChips() {
  const epics = epicsFor(state.surface);
  const ids = Object.keys(epics);
  if (!els.epicChips) return;
  if (!ids.length) {
    els.epicChips.innerHTML = `<span class="chip chip-muted">No epics yet</span>`;
    return;
  }
  els.epicChips.innerHTML = ids
    .map((id) => {
      const epic = epics[id];
      const on = id === state.epic ? " active" : "";
      const screen = id === state.epic ? currentScreenId() : "";
      return `<a class="chip ${epic.chipClass || ""}${on}" data-epic="${id}" href="${routeHash(state.surface, id, screen)}">${epic.label}</a>`;
    })
    .join("");
}

function epicDescription(epic) {
  if (state.journeySolo === "old") return "Current journey only";
  if (state.journeySolo === "new") return "New idea only";
  return epic?.description || "Add an epic for this surface to start.";
}

function scopeHintText(flow) {
  const label = SURFACES[state.surface]?.label || "";
  if (!flow.length) return `${label} — no steps yet`;
  if (!isDualJourney()) return `${label} · ${flow.length} steps`;
  if (state.journeySolo === "old") return `${label} · current journey`;
  if (state.journeySolo === "new") return `${label} · new idea`;
  return `${label} · current vs idea`;
}

function syncJourneyButtons() {
  const dual = isDualJourney();
  if (els.journeyRow) els.journeyRow.hidden = !dual;
  els.soloOldBtn?.classList.toggle("is-active", state.journeySolo === "old");
  els.soloNewBtn?.classList.toggle("is-active", state.journeySolo === "new");
  if (els.undoSoloBtn) els.undoSoloBtn.hidden = !state.journeySolo;
  document.querySelectorAll(".phone-label[data-solo]").forEach((btn) => {
    btn.classList.toggle("is-active", state.journeySolo === btn.dataset.solo);
  });
  document.querySelectorAll(".phone-stage[data-journey]").forEach((stage) => {
    const back = stage.querySelector(".phone-back");
    if (back) back.hidden = state.journeySolo !== stage.dataset.journey;
  });
}

function syncSurfaceSwitch() {
  els.surfaceSwitch?.querySelectorAll("[data-surface]").forEach((btn) => {
    const id = btn.dataset.surface;
    const on = id === state.surface;
    btn.classList.toggle("active", on);
    btn.setAttribute("aria-selected", String(on));
    btn.setAttribute("href", routeHash(id, on ? state.epic : firstEpicId(id), on ? currentScreenId() : ""));
  });
}

function syncScenario() {
  document.documentElement.classList.toggle("scenario-error", state.scenario === "error");
  document.querySelectorAll("#demoBar [data-scenario]").forEach((btn) => {
    const on = btn.dataset.scenario === state.scenario;
    btn.classList.toggle("active", on);
    btn.setAttribute("aria-pressed", String(on));
  });
}

function updateChips() {
  const epic = activeEpic();
  const flow = activeFlow();
  const empty = !flow.length;
  const mobile = !isWebsite();
  renderEpicChips();
  if (els.sidebarEpicName) els.sidebarEpicName.textContent = epic?.label || "No epic yet";
  if (els.sidebarEpicDesc) els.sidebarEpicDesc.textContent = epicDescription(epic);
  if (els.scopeHint) els.scopeHint.textContent = scopeHintText(flow);
  syncJourneyButtons();
  syncSurfaceSwitch();
  syncScenario();
  if (els.phoneColumn) els.phoneColumn.hidden = !mobile || empty;
  if (els.webColumn) els.webColumn.hidden = mobile;
  if (els.scopeEmptyPhone) els.scopeEmptyPhone.hidden = !mobile || !empty;
  syncDemoControls(empty);
}

function visibleDemoControls() {
  const requested = activeEpic()?.demoControls || [];
  return requested.filter((id) => id !== "scenario" || state.journeySolo !== "old");
}

function autoplayHintText() {
  if (!isDualJourney()) return activeEpic()?.autoplayHint || "Walks the screens in order";
  if (state.journeySolo === "old") return "Walks the current journey";
  if (state.journeySolo === "new") return "Walks the new idea";
  return "Walks both phones through the steps";
}

function syncDemoControls(empty) {
  const controls = visibleDemoControls();
  document.querySelectorAll("[data-demo-control]").forEach((line) => {
    line.hidden = !controls.includes(line.dataset.demoControl);
  });
  if (els.autoplayHint) els.autoplayHint.textContent = autoplayHintText();
  if (els.demoBar) els.demoBar.hidden = empty || !controls.length;
}

function fitPreview() {
  if (isWebsite()) {
    fitToStage(els.webColumn, "--web-scale", 0.25);
    return;
  }
  if (isDualJourney()) {
    fitDualPhones();
    return;
  }
  fitToStage(els.phoneColumn, "--phone-scale", 0.32);
}

function fitDualPhones() {
  const stage = document.querySelector(".stage-inner");
  const sample = document.querySelector(".phone-stage .phone");
  if (!stage || !sample) return;
  document.documentElement.style.setProperty("--phone-scale", "1");
  const cellWidth = state.journeySolo ? stage.clientWidth : stage.clientWidth / 2;
  const margin = 32;
  const pills = 48;
  const scale = Math.min(
    (cellWidth - margin) / sample.offsetWidth,
    (stage.clientHeight - margin - pills) / sample.offsetHeight
  );
  document.documentElement.style.setProperty("--phone-scale", String(Math.max(0.28, Math.min(1, scale))));
}

function fitToStage(column, cssVar, minScale) {
  const stage = document.querySelector(".stage-inner");
  if (!stage || !column || column.hidden) return;
  document.documentElement.style.setProperty(cssVar, "1");
  const margin = 16;
  const scale = Math.min(
    (stage.clientWidth - margin) / column.offsetWidth,
    (stage.clientHeight - margin) / column.offsetHeight
  );
  document.documentElement.style.setProperty(cssVar, String(Math.max(minScale, scale)));
}

function isTyping() {
  const active = document.activeElement;
  return /^(INPUT|TEXTAREA|SELECT)$/.test(active?.tagName || "") || Boolean(active?.isContentEditable);
}

function onKeydown(event) {
  if (isTyping()) return;
  if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
    event.preventDefault();
    stepBoth(event.key === "ArrowRight" ? 1 : -1);
  }
  if (event.key === " ") {
    event.preventDefault();
    if (state.isPlaying) pauseDemo();
    else playDemo();
  }
}

function bindEvents() {
  window.addEventListener("hashchange", onRouteChange);
  window.addEventListener("popstate", onRouteChange);
  window.addEventListener("resize", fitPreview);
  document.addEventListener("keydown", onKeydown);

  document.querySelectorAll("#demoBar [data-scenario]").forEach((btn) => {
    btn.addEventListener("click", () => {
      state.scenario = btn.dataset.scenario;
      syncScenario();
    });
  });
  els.btnPlay.addEventListener("click", playDemo);
  els.btnPause.addEventListener("click", pauseDemo);
  els.autoplaySpeed.addEventListener("change", setupAutoplay);

  els.soloOldBtn?.addEventListener("click", () => setJourneySolo("old"));
  els.soloNewBtn?.addEventListener("click", () => setJourneySolo("new"));
  els.undoSoloBtn?.addEventListener("click", () => setJourneySolo(null));
  document.querySelectorAll(".phone-label[data-solo]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const which = btn.dataset.solo;
      setJourneySolo(state.journeySolo === which ? null : which);
    });
  });
  document.querySelectorAll(".phone-back[data-back]").forEach((btn) => {
    btn.addEventListener("click", () => setJourneySolo(null));
  });
  document.querySelectorAll("[data-step-journey]").forEach((btn) => {
    btn.addEventListener("click", () => stepJourney(btn.dataset.stepJourney, Number(btn.dataset.stepDelta)));
  });
  els.prevBtn?.addEventListener("click", () => stepBoth(-1));
  els.nextBtn?.addEventListener("click", () => stepBoth(1));
}


/* ── js/app.js ── */







hooks.bindActiveScreen = bindActiveScreen;
hooks.updateChrome = updateChips;
hooks.fitPreview = fitPreview;
hooks.applySurfaceClass = applySurfaceClass;

function init() {
  document.getElementById("app").innerHTML = shellHtml;
  cacheElements();
  mountScreens();
  bindEvents();
  applyRoute();
  updatePlayState();
}

init();
